/* ⛔ GENERATED by kit/build.mjs from i18n/id.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["id"] = {"hero.badge":"Versi 1.5.0 adalah rilis saat ini","hero.headline":"<span class=\"hl-muted\">Tampil percaya diri.</span> <span class=\"hl-bright\">Tetap pada naskah.</span>","hero.sub":"Teleprompter untuk komputer Anda yang membaca pada tempo manusia yang sebenarnya — karakter per detik, atau BPM lagu Anda — dan menandai setiap jeda yang Anda tulis di naskah.","hero.chipDesktop":"Aplikasi desktop","hero.chipLanguages":"18 bahasa","hero.chipNoAccount":"Tanpa akun","what.is.title":"Apa ini","what.is.lead":"Membaca naskah di depan kamera biasanya berarti gulungan yang terlalu cepat atau terlalu lambat, jeda yang terlupa, dan layar kedua yang tertinggal satu baris.","what.is.body":"Freally Teleprompt adalah teleprompter untuk komputer Anda. Buka naskah yang dikirimkan kepada Anda, atur kecepatannya dalam karakter per detik atau sesuai BPM lagu Anda, dan ia berjalan dengan kecepatan manusia yang nyata — setiap jeda yang Anda tulis ditandai di naskah, dan setiap layar berada di kata yang sama.","what.title":"Apa yang dilakukannya","features.pace.title":"Tempo baca yang sebenarnya","features.pace.body":"Atur kecepatan dalam karakter per detik, atau dalam BPM dari 20 sampai 250 untuk membaca seirama dengan lagu — bukan tombol putar sembarang dari 1 sampai 10.","features.pauses.title":"Jeda yang bisa Anda lihat","features.pauses.body":"Ketik -- untuk jeda singkat atau --3 untuk berhenti tiga detik. Masing-masing menjadi cip di editor, dan menyala saat pembacaan mencapainya.","features.screens.title":"Semua layar pada kata yang sama","features.screens.body":"Satu mesin, dihitung dalam karakter, menggerakkan pratinjau Anda, proyektor pembaca — dibalik untuk kaca prompter jika perlu — dan ponsel di jaringan Anda sendiri, sehingga semuanya tidak pernah berselisih.","features.import.title":"Buka berkas yang dikirimkan kepada Anda","features.import.body":"Impor berkas Word, RTF, PDF, teks polos, dan Markdown sebagai teks prompter yang bersih, dengan laporan tentang apa pun yang tidak bisa dibawanya.","features.markers.title":"Temukan jalan Anda","features.markers.body":"Baris yang diawali # menjadi penanda bagian di daftar lompatan, di samping cari dan ganti serta jumlah kata yang diperbarui langsung.","features.timing.title":"Membaca tepat waktu","features.timing.body":"Ketuk tempo Anda sendiri, dengarkan klik dengan hitungan masuk, lihat birama dan ketukan, dan berlatih untuk mendapatkan laporan waktu per bagian.","features.control.title":"Pedal, remote, dan tombol global","features.control.body":"Setiap perintah punya tombol yang bisa Anda ubah. Pedal kaki dan remote presentasi ditetapkan seperti tombol biasa, dan sebuah tombol bisa bekerja bahkan saat aplikasi tidak berada di depan.","features.writing.title":"Bantuan saat Anda menulis","features.writing.body":"Pelengkapan otomatis dalam 18 bahasa dari daftar kata di dalam aplikasi, dan dikte dalam bahasa Inggris: ucapkan, dan kata-kata Anda tertulis ke dalam naskah.","features.private.title":"Milik Anda, di komputer Anda","features.private.body":"Tanpa akun, tanpa telemetri, tanpa awan. Naskah adalah berkas biasa di komputer Anda, dan aplikasi hanya menanyakan satu hal ke internet: apakah ada versi yang lebih baru.","ladder.title":"Jalan menuju 2.0","ladder.intro":"Setiap rilis sejauh ini, lalu langkah-langkah yang direncanakan menuju 2.0. Sebuah langkah mendapat nomor versinya saat dirilis, dan rencana bisa berubah.","ladder.rung.v0.100.0":"Fondasi: aplikasi berjalan di Windows, macOS, dan Linux, meminta Anda menyetujui lisensinya, dan menggulir naskah dengan mesin berbasis karakter dari Freally Capture.","ladder.rung.v0.200.0":"Teleprompter mandiri: pustaka naskah, cip jeda, proyektor untuk pembaca dengan pembalikan cermin, cermin ke ponsel di jaringan Anda sendiri, kontrol pemutaran sungguhan, tempo BPM, dan pembacaan lantang.","ladder.rung.v0.300.0":"Pelengkapan otomatis luring: menyelesaikan kata dan frasa umum saat Anda mengetik, dalam ke-18 bahasa, dari daftar kata di dalam aplikasi.","ladder.rung.v1.0.0":"Rilis lengkap pertama: tur sambutan satu menit, pemeriksaan papan ketik dan pembaca layar, tema yang mengikuti sistem Anda, dan pembaruan yang baru terpasang setelah Anda setuju.","ladder.rung.v1.1.0":"Tulis naskah Anda dengan berbicara: dikte yang berjalan di komputer Anda, tanpa ada yang perlu dilatih.","ladder.rung.v1.2.0":"Dikte, dituntaskan: tombol rekam yang layak, kata-kata yang mendarat di posisi kursor Anda, dan urungkan yang menarik kembali satu hal yang Anda ucapkan.","ladder.rung.v1.3.0":"Membaca tepat waktu: tempo yang Anda ketuk agar sesuai dengan pembawaan Anda, metronom, penghitung birama dan ketukan, latihan dengan laporan waktu, dan label yang tidak memakan waktu baca.","ladder.rung.v1.4.0":"Memasukkan naskah: impor berkas Word, RTF, PDF, teks, dan Markdown, penanda bagian dengan daftar lompatan, cari dan ganti, serta statistik naskah.","ladder.rung.v1.5.0":"Apa pun di ruangan bisa mengendalikannya: pedal kaki dan remote presentasi, tombol yang bekerja saat aplikasi tidak berada di depan, dan peta setiap perintah yang bisa ditetapkan ulang.","ladder.rung.rig":"Dibuat untuk perangkat syuting: pembalikan vertikal untuk kaca yang dipasang di atas, panduan lensa dan margin aman, tampilan waktu berjalan dan sisa waktu, serta prasetel untuk membaca dari kejauhan.","ladder.rung.takes":"Tak ada pengambilan yang hilang: pemulihan suntingan yang belum disimpan setelah aplikasi mogok, pengaturan yang ikut bersama setiap naskah, riwayat versi lokal, dan ekspor ke PDF sebagai cadangan di atas kertas.","ladder.rung.writing":"Bantuan menulis: pencari rima, jumlah suku kata untuk setiap baris, pemeriksaan kata yang sulit diucapkan, dan saran jeda — dari kamus, tanpa model.","ladder.rung.remote":"Kendalikan dari mana saja: halaman kendali seukuran ponsel, ditambah MIDI dan OSC untuk meja kendali yang sudah Anda pakai — hanya di jaringan Anda sendiri, dan mati secara bawaan.","ladder.rung.show":"Jalankan seluruh acara: susunan acara dengan durasi untuk setiap item, lebih dari satu keluaran prompter, serta tampilan hitung mundur besar dan lampu isyarat untuk lantai produksi.","ladder.rung.record":"Rekam sambil membaca prompter: rekaman kamera web saat naskah berjalan, atau hanya audio dengan penanda bagian Anda ditulis ke dalam berkas sebagai bab.","ladder.rung.languages":"Setiap naskah, setiap bahasa: penekanan pada satu kata, furigana di atas baris, penyempurnaan kanan-ke-kiri untuk bahasa Arab, serta teks vertikal untuk bahasa Jepang dan Tionghoa.","ladder.rung.v2.0.0":"Versi 2.0: semua yang di atas, di Windows, macOS, dan Linux.","ladder.note":"Selesai berarti sudah dirilis dan diberi tag. Meski begitu, situs ini tidak menawarkan unduhan.","honest.title":"Hal-hal yang oleh kebanyakan situs diletakkan di paling bawah","honest.model.title":"Dikte memakai model ucapan","honest.model.body":"Dikte adalah satu-satunya bagian aplikasi yang memakai pembelajaran mesin: Vosk, pengenal ucapan sumber terbuka, dengan model bahasa Inggris kecil berukuran sekitar 40 MB di dalam aplikasi. Dikte berjalan di komputer Anda, tidak mengunggah atau mengunduh apa pun, hanya memahami bahasa Inggris, dan tetap mati sampai Anda menyalakannya. Selebihnya adalah kode biasa dan daftar kata.","honest.update.title":"Ia menanyakan satu pertanyaan ke internet","honest.update.body":"Setiap kali dijalankan, aplikasi bertanya ke GitHub apakah ada versi yang lebih baru. Permintaan itu tidak membawa naskah, pengaturan, maupun pengenal apa pun, dan tidak ada yang terpasang kecuali Anda setuju. Selebihnya bekerja tanpa koneksi sama sekali.","honest.voice.title":"Ia tidak mengikuti suara Anda","honest.voice.body":"Sebagian teleprompter menggulir dengan mendengarkan Anda membaca. Freally Teleprompt 1.5.0 menggulir pada tempo yang Anda atur, dan Anda, sebuah tombol, atau pedal mengambil alih saat pembacaan berubah. Mode mengikuti suara pernah dicoba di 1.0.0 dan dihapus di 1.1.0.","honest.downloads.title":"Tidak ada unduhan di situs ini","honest.downloads.body":"Tidak ada tautan unduhan, tidak ada tombol, dan tidak ada beta. Kode sumbernya juga privat.","site.tagline":"Tampil percaya diri. Tetap pada naskah.","footer.licence":"Berpemilik — Seluruh Hak Dilindungi. © Mike Weaver. Gratis digunakan saat ini; versi mendatang mungkin dijual. Bukan sumber terbuka.","footer.yours":"Naskah Anda adalah milik Anda. Naskah itu tetap di komputer Anda, dan pembuat aplikasi tidak pernah menerima, menyimpan, atau meneruskannya.","featuresPage.lead":"Teleprompter untuk Windows, macOS, dan Linux yang membaca pada tempo manusia yang sebenarnya, menjaga semua layar pada kata yang sama, dan membuka naskah yang dikirimkan kepada Anda.","featuresPage.version":"Halaman ini menjelaskan Freally Teleprompt 1.5.0, versi yang sudah dirilis: semua yang ada di sini ada di 1.5.0, dan tidak ada yang masih direncanakan tercantum di sini.","featuresPage.numbers.intro":"Setiap angka adalah apa yang dilakukan versi 1.5.0, dihitung dari kodenya. Tidak ada yang dibulatkan ke atas.","featuresPage.numbers.paces":"cara mengatur tempo: karakter per detik atau BPM","featuresPage.numbers.bpm":"BPM: rentang yang bisa dibacanya mengikuti ketukan","featuresPage.numbers.formats":"jenis berkas yang bisa diimpornya: Word, RTF, PDF, teks polos, dan Markdown","featuresPage.numbers.systems":"sistem operasi: Windows, macOS, dan Linux","featuresPage.numbers.languages":"bahasa, di aplikasi dan di pelengkapan otomatisnya","featuresPage.numbers.words":"kata dalam daftar pelengkapan otomatisnya, ditambah 344.891 frasa","featuresPage.numbers.accounts":"akun yang perlu dibuat","featuresPage.numbers.model":"model ucapan, untuk dikte: di komputer Anda, dan mati sampai Anda menyalakannya","featuresPage.numbers.price":"harga saat ini","featuresPage.free.title":"Gratis saat ini","featuresPage.free.body":"Semua yang dilakukan Freally Teleprompt 1.5.0 gratis saat ini, untuk semua orang: tanpa tingkatan berbayar, tanpa langganan, tanpa akun, dan tanpa masa uji coba yang habis.","featuresPage.cards.title":"Apa yang dilakukan versi 1.5.0","featuresPage.cards.pace.title":"Tempo baca yang sebenarnya","featuresPage.cards.pace.body":"Karakter per detik, atau BPM dari 20 sampai 250 untuk lirik dan bait yang dibaca mengikuti lagu. Ubah salah satunya saat naskah berjalan dan guliran langsung menyesuaikan temponya.","featuresPage.cards.pauses.title":"Cip jeda","featuresPage.cards.pauses.body":"Ketik -- untuk jeda singkat atau --N untuk berhenti N detik. Masing-masing adalah satu cip yang tidak bisa dipecah kursor, menyala saat pembacaan mencapainya, dan diubah pembacaan lantang menjadi keheningan sungguhan.","featuresPage.cards.engine.title":"Semua layar pada kata yang sama","featuresPage.cards.engine.body":"Pratinjau, proyektor, dan perangkat di jaringan Anda mengikuti satu mesin, dihitung dalam karakter, sehingga semuanya sepakat tentang kata yang sedang dibaca bahkan pada ukuran teks yang berbeda.","featuresPage.cards.projector.title":"Proyektor untuk pembaca","featuresPage.cards.projector.body":"Layar penuh di tampilan mana pun, dicerminkan untuk kaca pemisah sinar, dengan kontrol pemutaran dan tombolnya sendiri untuk orang yang membaca.","featuresPage.cards.mirror.title":"Cermin ke ponsel dan tablet","featuresPage.cards.mirror.body":"Mati sampai Anda menyalakannya. Tautan dan kode QR membuka naskah di peramban mana pun di jaringan Anda sendiri: baca-saja, dengan kunci yang berubah setiap kali aplikasi dijalankan.","featuresPage.cards.import.title":"Impor Word, RTF, PDF, teks, dan Markdown","featuresPage.cards.import.body":"Teks prompter yang bersih dengan paragrafnya tetap terjaga, dan laporan yang menghitung apa yang tidak bisa dibawa — gambar, catatan kaki, komentar. Tidak ada yang disimpan sampai Anda mengatakannya.","featuresPage.cards.markers.title":"Penanda bagian, cari dan ganti","featuresPage.cards.markers.body":"Baris yang diawali # adalah penanda di bilah telusur dan di daftar lompatan. Cari dan ganti bisa mencocokkan huruf besar/kecil atau kata utuh, dan dibatalkan dengan sekali tekan.","featuresPage.cards.timing.title":"Tempo, klik, dan birama","featuresPage.cards.timing.body":"Ketuk tempo Anda agar BPM pas dengan pembawaan Anda sendiri, dengarkan klik dengan hitungan masuk, dan lihat birama dan ketukan di layar serta sebagai garis di bilah telusur.","featuresPage.cards.rehearsal.title":"Latihan dan laporan waktu","featuresPage.cards.rehearsal.body":"Baca sampai habis dan lihat waktu yang direncanakan setiap bagian dibandingkan waktu nyatanya, serta tempo yang benar-benar Anda pakai. Hanya waktu yang dicatat — tanpa mikrofon, tanpa audio.","featuresPage.cards.skip.title":"Label yang tidak memakan waktu","featuresPage.cards.skip.body":"Tandai Reff, [Bait 1], atau ## Bridge sebagai kata yang tidak Anda bawakan: semuanya tetap tampil di layar, diredupkan, dan tidak memakan waktu baca, sehingga lirik Anda tetap pada biramanya.","featuresPage.cards.control.title":"Pintasan, pedal, dan tombol global","featuresPage.cards.control.body":"Peta setiap perintah yang bisa dicari, dengan bentrokan yang ditandai. Pedal dan remote ditetapkan seperti tombol biasa, dan sebuah tombol bisa bekerja saat aplikasi lain berada di depan.","featuresPage.cards.writing.title":"Pelengkapan otomatis, dikte, dan pembacaan lantang","featuresPage.cards.writing.body":"Saran kata dan frasa dalam 18 bahasa dari daftar di dalam aplikasi, dikte bahasa Inggris yang berjalan di komputer Anda, dan pembacaan lantang dengan suara bawaan sistem Anda.","featuresPage.cards.look.title":"Tampilan Anda, bahasa Anda","featuresPage.cards.look.body":"Jenis huruf, ukuran, ketebalan, warna, margin, jarak baris, dan garis baca, di semua layar sekaligus. Aplikasi ini berbicara dalam 18 bahasa, dengan tema gelap atau terang.","featuresPage.cards.private.title":"Tanpa akun, tanpa awan","featuresPage.cards.private.body":"Naskah adalah berkas biasa di komputer Anda, dan tidak ada telemetri. Satu-satunya permintaan aplikasi ke internet adalah pemeriksaan versi yang lebih baru, dan tidak ada yang terpasang tanpa persetujuan Anda.","featuresPage.compare.title":"Berdampingan dengan teleprompter komersial","featuresPage.compare.intro":"Freally Teleprompt 1.5.0 — versi yang sudah dirilis, yang bisa Anda pakai hari ini — di samping enam aplikasi teleprompter komersial. Setiap sel untuk produk lain berasal dari halaman milik pembuatnya sendiri atau dari daftar di toko aplikasinya, diperiksa pada 2 Oktober 2026, dan harga dalam dolar AS per Oktober 2026.","featuresPage.compare.feature":"Fitur","featuresPage.compare.row.price":"Harga (USD, Oktober 2026)","featuresPage.compare.freeToday":"Gratis saat ini","featuresPage.compare.unit.perMonth":"per bulan","featuresPage.compare.unit.perYear":"per tahun","featuresPage.compare.unit.once":"sekali bayar","featuresPage.compare.unit.onSale":"harga diskon; biasanya $99","featuresPage.compare.row.systems":"Aplikasi desktop untuk Windows, macOS, dan Linux","featuresPage.compare.legend.yes":"ada","featuresPage.compare.legend.partly":"sebagian","featuresPage.compare.note.browser":"dan di peramban web","featuresPage.compare.row.noAccount":"Bisa dipakai tanpa membuat akun","featuresPage.compare.legend.no":"tidak ada","featuresPage.compare.legend.unknown":"belum diverifikasi","featuresPage.compare.row.offline":"Bekerja tanpa koneksi internet","featuresPage.compare.note.updateCheck":"hanya pemeriksaan pembaruan yang daring","featuresPage.compare.note.afterRegistration":"setelah mendaftar secara daring","featuresPage.compare.row.import":"Membuka berkas Word dan PDF","featuresPage.compare.note.ourFormats":"juga RTF, teks polos, dan Markdown","featuresPage.compare.note.wordIos":"Word hanya di iPhone dan iPad","featuresPage.compare.note.textRtf":"hanya teks polos dan RTF","featuresPage.compare.row.bpm":"Menyesuaikan guliran dengan tempo musik (BPM)","featuresPage.compare.row.pauses":"Jeda berwaktu yang ditulis di naskah","featuresPage.compare.row.mirror":"Teks cermin untuk kaca prompter","featuresPage.compare.row.devices":"Menampilkan naskah di perangkat lain","featuresPage.compare.note.ownNetwork":"di jaringan Anda sendiri, lewat peramban","featuresPage.compare.note.portal":"lewat portal pembuatnya, secara daring","featuresPage.compare.note.internet":"lewat internet","featuresPage.compare.note.btWifi":"lewat Bluetooth, Wi-Fi, atau internet","featuresPage.compare.note.displayOrLan":"layar kedua, atau perangkat lain di jaringan","featuresPage.compare.note.secondMonitor":"monitor kedua; tablet butuh aplikasi lain","featuresPage.compare.row.remotes":"Pedal kaki dan remote presentasi","featuresPage.compare.note.keyboardOnly":"hanya pintasan papan ketik","featuresPage.compare.row.voiceScroll":"Guliran mengikuti suara Anda","featuresPage.compare.note.removed":"dihapus di 1.1.0","featuresPage.compare.note.paidAddon":"tambahan berbayar","featuresPage.compare.summaryTitle":"Singkatnya","featuresPage.compare.summary":"Ringkasnya: dari ketujuh aplikasi ini, hanya Freally Teleprompt yang menyatakan menyesuaikan guliran dengan BPM dan menahan jeda berwaktu yang ditulis di naskah, dan hanya ia yang berjalan di Windows, macOS, dan Linux tanpa akun dan tanpa bayar.","featuresPage.compare.theyWinTitle":"Di mana mereka unggul","featuresPage.compare.theyWin":"Di mana mereka unggul: PromptSmart, Speakflow, dan Teleprompter.com menggulir dengan mengikuti suara Anda, dan TeleScroll juga bisa lewat tambahan berbayar; Freally Teleprompt 1.5.0 tidak. PromptSmart, Teleprompter.com, dan Teleprompter Pro punya aplikasi ponsel dan tablet yang merekam video saat Anda membaca dan menyimpan naskah Anda di awan mereka, dan Speakflow menambahkan alat menulis berbasis AI serta kolaborasi waktu nyata.","featuresPage.compare.asOf":"Kolom Freally Teleprompt adalah versi 1.5.0, yang sudah dirilis, sehingga tabel ini membandingkan apa yang bisa Anda pakai hari ini. Harganya adalah harga saat ini: Freally Teleprompt gratis saat ini, dan versi mendatang mungkin dijual. Produk lain juga berubah; tabel ini berlaku per 2 Oktober 2026.","featuresPage.why.title":"Mengapa ia dibuat seperti ini","featuresPage.why.engine.title":"Satu mesin, dihitung dalam karakter","featuresPage.why.engine.body":"Kecepatan adalah karakter per detik, sehingga pratinjau, proyektor, dan setiap ponsel bergerak melalui teks yang sama dengan laju yang sama berapa pun ukuran fontnya. Mesinnya ditulis dua kali, untuk inti aplikasi dan untuk antarmukanya, dan keduanya dijaga tetap identik.","featuresPage.why.import.title":"Konverter yang menyebutkan apa yang dibuangnya","featuresPage.why.import.body":"Impor menghitung apa yang tidak bisa dibawanya alih-alih menghilangkannya diam-diam, dan tidak pernah mengubah tanda pisah hasil atur huruf menjadi jeda yang tidak pernah ditulis siapa pun.","featuresPage.why.isolate.title":"Berkas yang rusak tidak bisa menghentikan pembacaan","featuresPage.why.isolate.body":"Dokumen dibaca di proses terpisah dengan batas waktu, sehingga PDF yang rusak hanya mengakhiri impor itu, bukan prompternya.","featuresPage.why.local.title":"Ia tetap di komputer Anda","featuresPage.why.local.body":"Tanpa akun, tanpa telemetri, dan tanpa awan. Naskah Anda adalah berkas teks biasa yang bisa Anda buka di editor mana pun, dan cermin jaringan tetap berada di jaringan Anda sendiri.","featuresPage.why.consent.title":"Tidak ada yang terjadi diam-diam di belakang Anda","featuresPage.why.consent.body":"Pengaturan hanya berubah saat Anda menekan Terapkan, tombol tingkat sistem hanya diklaim saat Anda memintanya, dan pembaruan hanya terpasang setelah Anda setuju.","featuresPage.why.keyboard.title":"Dalam jangkauan papan ketik","featuresPage.why.keyboard.body":"Setiap kontrol punya cincin fokus, dialog menjaga fokus tetap di dalamnya, bilah telusur adalah penggeser sungguhan, dan pengaturan kurangi gerakan serta kurangi transparansi dihormati.","featuresPage.coming.title":"Apa yang masih akan datang","featuresPage.coming.intro":"Dinyatakan terus terang, karena daftar fitur yang menyembunyikan kekurangannya tidak layak dibaca. Semua yang ada di halaman ini ada di 1.5.0; langkah-langkah sesudahnya ada di jalan menuju 2.0, masing-masing ditandai dengan statusnya.","featuresPage.limits.title":"Apa yang tidak dilakukan 1.5.0","featuresPage.limits.voice":"Ia tidak menggulir dengan mengikuti suara Anda: Anda yang mengatur tempo, dan sebuah tombol atau pedal mengambil alih saat pembacaan berubah.","featuresPage.limits.dictation":"Dikte hanya memahami bahasa Inggris; pelengkapan otomatis dan antarmuka mencakup ke-18 bahasa.","featuresPage.limits.phone":"Tidak ada aplikasi ponsel atau tablet: ponsel bisa menampilkan naskah lewat cermin jaringan, baca-saja, tetapi tidak bisa mengendalikannya.","featuresPage.limits.recording":"Ia tidak merekam video atau audio saat Anda membaca prompter.","featuresPage.limits.wayland":"Di Wayland pada Linux, tombol yang diatur untuk bekerja saat aplikasi lain berada di depan mungkin tidak berfungsi, karena Wayland tidak mengizinkan aplikasi memesan tombol untuk seluruh sistem; tombol di dalam aplikasi tidak terpengaruh.","featuresPage.coming.downloads":"Tidak ada unduhan di situs ini, dan tidak ada juga di halaman ini.","docs.intro":"Cara memakai Freally Teleprompt, dari peluncuran pertama hingga pembacaan di perangkat syuting.","docs.start.title":"Memulai","docs.write.title":"Menulis naskah","docs.import.title":"Mengimpor dokumen","docs.find.title":"Cari dan ganti","docs.markers.title":"Penanda bagian","docs.pauses.title":"Cip jeda","docs.pacing.title":"Mengatur kecepatan: karakter per detik atau BPM","docs.tempo.title":"Tempo, birama, dan klik","docs.rehearsal.title":"Latihan dan laporan waktu","docs.skip.title":"Kata yang tidak Anda bawakan","docs.playback.title":"Pemutaran dan kontrolnya","docs.shortcuts.title":"Pintasan, pedal, dan tombol global","docs.countdown.title":"Hitung mundur sebelum mulai","docs.projector.title":"Proyektor","docs.mirror.title":"Cermin jaringan","docs.readAloud.title":"Pembacaan lantang","docs.autocomplete.title":"Pelengkapan otomatis","docs.dictation.title":"Dikte","docs.settings.title":"Tampilan, bahasa, dan pengaturan","docs.access.title":"Tur dan aksesibilitas","docs.problems.title":"Masalah dan pembaruan","docs.privacy.title":"Privasi dan jaringan","docs.start.p1":"Freally Teleprompt adalah teleprompter untuk Windows, macOS, dan Linux, bagi pembawa acara, kreator siaran langsung, pembuat siniar, aktor, penyanyi, dan rapper. Aplikasi ini terbuka sebagai satu jendela — naskah Anda, editor, pratinjau, dan kendali proyektor — dan tidak membutuhkan akun.","docs.start.p2":"Saat pertama kali dibuka, aplikasi menampilkan perjanjian lisensinya. Gulir sampai akhir, lalu pilih Saya Setuju, atau Tolak & Keluar. Aplikasi tidak bisa dipakai sampai Anda setuju; jawaban Anda diingat, dan Anda hanya ditanya lagi jika perjanjiannya berubah.","docs.start.p3":"Setelah itu, tur satu menit menunjukkan editor, kendali tempo, dan proyektor. Ketik atau tempel naskah, atur tempo Anda, lalu tekan putar.","docs.start.p4":"Tidak ada unduhan di situs ini, dan kode sumbernya privat.","docs.write.p1":"Naskah adalah berkas .ftscript: teks polos dalam satu folder, bisa dibaca di editor teks mana pun. Buka Naskah di bilah alat untuk membuat, membuka, mengganti nama, dan menghapusnya. Daftar terbaru membawa Anda kembali ke apa yang sedang Anda kerjakan, semuanya tersimpan saat Anda mengetik, dan aplikasi membuka kembali naskah yang terakhir Anda buka.","docs.write.p2":"Ketik di editor atau tempel dari mana saja. Di bawah perkiraan waktu baca, jumlah kata dan karakter yang diperbarui langsung menunjukkan apa yang benar-benar akan Anda bawakan — label yang dilewati dan tanda jeda tidak dihitung — dan sebuah peringatan menandai baris mana pun yang cukup panjang untuk menjadi satu paragraf utuh.","docs.import.p1":"Tekan Impor di bilah alat dan pilih dokumen Word (.docx), RTF, PDF, berkas teks polos, atau berkas Markdown. Anda melihat teks yang dihasilkannya, beserta sebuah laporan, sebelum apa pun disimpan.","docs.import.p2":"Paragraf dipertahankan; tebal, font, dan warna diratakan, karena prompter menampilkan satu jenis huruf. Tanda kutip melengkung, tanda pisah panjang, dan elipsis menjadi versi polosnya, dan berkas yang disimpan dengan pengodean lama dibaca dengan benar, dan laporannya menyebutkan hal itu.","docs.import.p3":"Gambar, catatan kaki, komentar, kepala dan kaki halaman, alamat tautan, dan objek tertanam dihitung dan dicantumkan, tidak pernah dibuang diam-diam. PDF tidak punya struktur seperti itu, jadi untuk PDF laporannya menyatakan bahwa ia tidak bisa mengetahuinya.","docs.import.p4":"Beri nama naskahnya — nama disarankan dari berkasnya — lalu tekan Impor. Naskah ditambahkan ke pustaka Anda dan dibuka, dan tidak pernah menimpa naskah yang sudah ada. Judul Markdown tiba sebagai baris #, sehingga naskah Markdown datang lengkap dengan penanda bagiannya.","docs.import.p5":"Tanda pisah hasil atur huruf menjadi tanda hubung biasa, dan dua tanda itu tidak pernah berubah menjadi jeda, sehingga naskah drama yang diimpor tidak tiba penuh jeda yang tidak pernah ditulis siapa pun. Berkas teks yang Anda tulis dengan tanda jeda sungguhan tetap mempertahankannya.","docs.find.p1":"Tekan Ctrl+F, atau Cari di bilah alat, untuk mencari di naskah yang terbuka. Jumlah kecocokan diperbarui saat Anda mengetik; Enter menuju kecocokan berikutnya dan Shift+Enter ke yang sebelumnya, berputar kembali di kedua ujung.","docs.find.p2":"Cocokkan huruf besar/kecil dan Hanya kata utuh mempersempit pencarian, dan apa yang Anda ketik dicari secara harfiah. Ganti mengubah kecocokan saat ini dan Ganti semua mengubah semuanya; keduanya dibatalkan dengan satu kali Ctrl+Z.","docs.markers.p1":"Awali sebuah baris dengan # — # Bait 2, # Tanya Jawab, ## Bridge — dan baris itu menjadi penanda bagian. Setiap baris yang merupakan salah satu kata lewati Anda, seperti [Reff], juga menjadi penanda. Tidak ada yang perlu disiapkan.","docs.markers.p2":"Penanda muncul di daftar lompatan di samping bilah telusur, yang menunjukkan bagian tempat Anda berada, dan digaris pada bilah telusur itu sendiri. Bagian berikutnya dan Bagian sebelumnya menelusurinya; Bagian sebelumnya lebih dulu menuju awal bagian tempat Anda berada, seperti tombol lagu sebelumnya. Memilih salah satunya menggerakkan semua layar, termasuk proyektor.","docs.pauses.p1":"Ketik -- (spasi, dua tanda hubung, spasi) untuk jeda singkat, atau --N untuk berhenti N detik. Masing-masing menjadi cip di editor: kursor hanya berada sebelum atau sesudahnya, satu Backspace menghapusnya, dan Shift dengan tombol panah memilihnya utuh. Atur panjang -- biasa di Pengaturan → Membaca.","docs.pauses.p2":"Salin dan tempel membawa cip secara utuh, dan teks yang ditempel dirapikan spasinya sehingga setiap jeda mendarat sebagai cip yang bersih. Saat naskah diputar, setiap jeda menyala ketika pembacaan mencapainya dan guliran berhenti sepanjang jeda itu — di pratinjau, proyektor, dan cermin jaringan sekaligus.","docs.pacing.p1":"Atur kecepatan dalam karakter per detik: laju baca sungguhan yang diikuti semua layar, berapa pun ukuran fontnya. Atau beralih ke BPM, dari 20 sampai 250, untuk membaca lirik dan bait seirama dengan lagu.","docs.pacing.p2":"Keduanya menggerakkan mesin yang sama, dan mengubah salah satunya saat naskah berjalan langsung menyesuaikan temponya.","docs.tempo.p1":"Sebuah tempo menjadi kecepatan baca lewat satu angka: berapa karakter yang Anda baca dalam satu ketukan. Di Pengaturan → Pewaktuan → Tempo Anda sendiri, tekan Ketuk tiga kali atau lebih pada tempo yang Anda bawakan, lalu pilih Pakai tempo ini; Kembali ke bawaan membatalkannya. Setelah itu kotak BPM hanya menawarkan tempo yang bisa dijangkau mesin.","docs.tempo.p2":"Dengan BPM menyala, atau klik dinyalakan, birama dan ketukan muncul di atas bilah telusur dan garis birama digambar pada bilah itu. Atur Ketukan per birama, dari 2 sampai 12, di Pengaturan → Pewaktuan.","docs.tempo.p3":"Centang Mainkan klik pada tempo saat ini untuk tik lembut pada setiap ketukan, lebih tinggi pada ketukan pertama setiap birama; hitung mundur awal menjadi hitungan masuknya. Aplikasi membuat suaranya sendiri dan mengatur waktu setiap tik terhadap jam audio, sehingga tidak bergeser. Klik tetap diam selama pembacaan lantang sedang berbicara.","docs.rehearsal.p1":"Centang Berlatih dan catat waktu baca saya di bawah kontrol pemutaran, tekan putar, dan bacalah dengan lantang seperti pada hari-H. Jeda, mundur, ubah kecepatan: semuanya menjadi bagian dari pengukuran.","docs.rehearsal.p2":"Hapus centangnya dan laporan latihan terbuka: satu baris per bagian, dengan waktu yang seharusnya pada tempo Anda, waktu yang benar-benar dipakai, dan selisihnya. Bagian adalah paragraf Anda, atau penanda bagian Anda jika naskahnya dibagi dengan penanda. Jika Anda membaca dengan tempo berbeda, laporan menawarkan kecepatan itu, dan satu klik menerapkannya.","docs.rehearsal.p3":"Saat Anda berlatih, peringatan yang tenang muncul begitu pembacaan tertinggal atau mendahului rencananya tiga detik atau lebih. Latihan hanya mencatat waktu dan tidak ada yang lain: tidak membuka mikrofon, tidak menyimpan audio, dan tidak bisa berjalan bersamaan dengan pembacaan lantang.","docs.skip.p1":"Label bagian — Reff, Bait 2, Bridge — adalah patokan yang Anda lihat datang tetapi tidak pernah Anda ucapkan. Cantumkan di Pengaturan → Pewaktuan → Kata yang tidak Anda bawakan, satu per baris. Daftarnya mulai kosong, karena daftar ini mengubah cara waktu sebuah naskah dihitung.","docs.skip.p2":"Baris yang hanya berisi label dilewati seluruhnya: kurung siku, tanda pagar, titik dua, dan angka di belakangnya diabaikan, sehingga Reff, [Bait 1], ## Bridge, dan Reff: semuanya cocok. Kata yang sama di dalam baris sungguhan hanya melewati dirinya sendiri. Pencocokan mengabaikan huruf besar dan hanya mencocokkan kata utuh.","docs.skip.p3":"Teks yang dilewati tetap tampil di layar, diredupkan, sehingga pembaca tetap melihatnya datang, dan pembacaan lantang tidak pernah mengucapkannya. Karena label tidak memakan waktu, guliran langsung melewatinya — dan lirik Anda tetap pada birama tempat Anda menulisnya.","docs.playback.p1":"Putar, jeda, berhenti, mundur, dan maju cepat adalah tombol di layar; tahan mundur atau maju cepat agar terus berjalan. Putar roda tetikus untuk menggeser posisi, klik sebuah kata untuk mulai dari situ, atau arahkan penunjuk ke bilah telusur untuk melihat kata-kata di titik itu.","docs.playback.p2":"Bilah telusur menunjukkan waktu baca yang telah berjalan dan totalnya, termasuk jeda. Garis baca menahan kata yang sedang dibaca di posisinya, dan kata terakhir yang menyala tidak pernah tergulir keluar dari pandangan.","docs.shortcuts.p1":"Buka Pintasan di bilah alat. Tekan penetapan yang ingin Anda ubah, lalu tekan tombol, remote, atau pedal yang Anda inginkan; Escape membiarkannya seperti semula. Cari berdasarkan nama perintah atau berdasarkan tombolnya sendiri. Jika dua perintah memakai tombol yang sama, kedua barisnya menyebutkannya; hapus salah satunya dengan ×, atau pilih Kembalikan ke bawaan.","docs.shortcuts.p2":"Sebagian besar pedal kaki dan remote presentasi mengirim tombol biasa, umumnya F13 sampai F24, sehingga bisa ditetapkan tanpa driver dan tanpa penyiapan. Penetapan mengikuti tombol fisiknya, bukan huruf yang tercetak di atasnya, sehingga tetap berlaku meski tata letak papan ketik berganti.","docs.shortcuts.p3":"Kolom Di mana saja meminta sistem Anda mengirimkan tombol bahkan saat aplikasi lain berada di depan — aplikasi kamera, DAW, atau OBS. Tidak ada yang diklaim sampai Anda mengaturnya, dan tombol yang sudah dimiliki program lain akan memberi tahu Anda. Di Wayland pada Linux, aplikasi tidak bisa memesan tombol untuk seluruh sistem, dan dialognya memberi tahu Anda.","docs.shortcuts.p4":"Saat Anda menulis, spasi, tombol panah, dan Home mengetik seperti biasa: tombol tunggal hanya menjalankan perintahnya di luar editor.","docs.countdown.p1":"Atur Hitung mundur sebelum mulai di Pengaturan → Membaca, dan menekan putar akan menghitung mundur sekian detik lebih dulu, di pratinjau dan proyektor, sehingga pembaca punya waktu sejenak sebelum kata pertama bergerak. Dengan klik menyala, hitung mundur itu juga menjadi hitungan masuk.","docs.projector.p1":"Tekan Buka proyektor dan pilih layar tempat pembaca membaca: naskah memenuhi layar itu dari tepi ke tepi. Nyalakan cermin untuk kaca pemisah sinar, yang jika tidak akan memantulkan tulisan terbalik. Proyektor punya kontrol pemutaran, bilah telusur, dan tombolnya sendiri untuk orang yang membaca.","docs.projector.p2":"Pratinjau dan proyektor menata naskah dengan lebar yang sama lalu menskalakannya agar pas, sehingga keduanya memutus baris di tempat yang sama. Pastikan teks yang dicerminkan terbaca dengan benar lewat kaca Anda sendiri sebelum syuting.","docs.mirror.p1":"Untuk menampilkan naskah di ponsel, tablet, atau laptop kedua, buka Pengaturan → Jaringan → Cerminkan ke jaringan saya dan centang Cerminkan naskah ke perangkat di jaringan saya. Centang juga Izinkan perangkat lain, bukan hanya komputer ini — tanpa itu, cermin hanya menjawab di komputer ini — lalu tekan Terapkan. Tautan dan kode QR muncul: pindai kodenya, atau buka tautannya di peramban di jaringan yang sama.","docs.mirror.p2":"Cermin mengikuti mesin yang sama, sehingga setiap perangkat berada pada kata yang sama dengan operator. Setiap perangkat mengatur ukuran teksnya sendiri dengan A− dan A+ tanpa mengubah layar orang lain.","docs.mirror.p3":"Halaman itu disajikan oleh aplikasi itu sendiri, langsung ke perangkat Anda — tidak pernah melalui situs web ini, yang toh tidak akan diizinkan peramban untuk menjangkau perangkat di jaringan Anda. Halaman itu baca-saja: tidak ada peramban yang bisa memulai, menghentikan, menelusuri, atau menyunting apa pun. Tautannya membawa kunci yang berubah setiap kali aplikasi dijalankan. Halaman itu memakai HTTP biasa, sehingga kuncinya tidak terenkripsi selama perjalanan: pakailah di jaringan yang Anda percaya, bukan di Wi-Fi publik.","docs.mirror.p4":"Jika sebuah perangkat tidak bisa tersambung: periksa kedua sakelar; pastikan perangkat itu berada di jaringan yang sama, bukan memakai data seluler atau jaringan tamu yang memisahkan perangkat; izinkan aplikasi melewati firewall Anda untuk jaringan pribadi saat sistem Anda bertanya; dan jika Pengaturan menyatakan cermin tidak bisa dijalankan, ganti port-nya lalu tekan Terapkan lagi.","docs.readAloud.p1":"Centang Bacakan dengan sintesis ucapan bawaan OS untuk mendengar naskah dengan suara bawaan sistem Anda: Windows OneCore atau SAPI, macOS AVSpeechSynthesis, atau Speech Dispatcher atau espeak-ng di Linux. Tidak ada suara yang disertakan bersama aplikasi.","docs.readAloud.p2":"Kontrol pemutaran, bilah telusur, dan klik pada sebuah kata menggerakkan ucapan, dan sorotannya ikut mengikuti — kata demi kata jika sistem melaporkan batas kata, dan pada tempo Anda jika tidak. Jeda menjadi keheningan singkat, dan -- tidak pernah dibacakan sebagai “tanda hubung”.","docs.readAloud.p3":"Pembacaan lantang hanya untuk pratinjau: tidak pernah menggerakkan proyektor. Kotak centangnya terkunci selama pembacaan sedang diputar atau dijeda, sampai Anda menekan Berhenti. Pastikan suaranya keluar di komputer yang akan Anda pakai untuk tampil, terutama di Linux.","docs.autocomplete.p1":"Saat Anda menulis, sisa kata muncul redup di depan kursor; selesaikan sebuah kata dan tekan spasi, dan ia bisa menawarkan seluruh frasa umum. Tab menerima, Esc menutup, dan terus mengetik mengabaikannya.","docs.autocomplete.p2":"Masing-masing dari 18 bahasa punya daftar kata dan frasanya sendiri — total 463.985 kata dan 344.891 frasa — di dalam aplikasi, dan hanya bahasa yang Anda pakai untuk menulis yang dimuat. Di Pengaturan → Editor, nyalakan atau matikan fitur ini dan pilih bahasanya, yang bisa berbeda dari bahasa aplikasi.","docs.autocomplete.p3":"Daftarnya dibangun dari kumpulan kalimat Tatoeba (CC BY 2.0 FR), yang dicantumkan di berkas NOTICE yang disertakan bersama aplikasi. Ini adalah pencarian kamus — instan, dapat diprediksi, dan luring, tanpa model.","docs.dictation.p1":"Buka Pengaturan → Suara, centang Tulis naskah saya dengan berbicara, lalu tekan Terapkan. Tombol rekam bundar muncul di atas naskah: tekan dan berbicaralah, dan apa yang Anda ucapkan dituliskan di posisi kursor Anda. Tekan lagi untuk berhenti; mikrofon hanya terbuka di antara kedua tekanan itu.","docs.dictation.p2":"Teks hasil dikte adalah teks naskah biasa, dan Ctrl+Z menarik kembali satu hal yang Anda ucapkan, bukan seluruh sesi. Bersiaplah merapikan tanda baca dan nama: dikte adalah jalan cepat menuju draf, bukan naskah jadi.","docs.dictation.p3":"Dikte hanya memahami bahasa Inggris. Dikte memakai Vosk, pengenal ucapan sumber terbuka, dengan model ucapan bahasa Inggris yang kecil — jaringan saraf terlatih berukuran sekitar 40 MB — yang disertakan di dalam aplikasi. Dikte berjalan di komputer Anda, bekerja tanpa koneksi, tidak mengunggah atau mengunduh apa pun, dan tidak menyimpan apa pun selain teks yang Anda lihat. Dikte mati sampai Anda menyalakannya. Jika naskah dicerminkan ke jaringan Anda, kata-kata hasil dikte sampai ke perangkat-perangkat itu begitu dituliskan, seperti mengetik.","docs.settings.p1":"Di Pengaturan → Tampilan, atur jenis huruf, ketebalan, dan warna teks, margin samping, jarak baris, dan posisi garis baca; ukuran font ada di Membaca. Semuanya berlaku untuk pratinjau, proyektor, dan cermin jaringan sekaligus.","docs.settings.p2":"Pengaturan bekerja pada draf: tidak ada yang berubah sampai Anda menekan Terapkan, dan Batal memulihkan apa yang Anda miliki sebelumnya. Pilih salah satu dari 18 bahasa, atau Sama seperti sistem saya. Temanya Gelap, Terang, atau Sama seperti sistem saya; permukaan baca tetap berkontras tinggi apa pun pilihan Anda.","docs.settings.p3":"Dengan Perkecil ke baki sistem menyala, di Pengaturan → Umum, memperkecil jendela menaruh aplikasi di baki alih-alih di bilah tugas. Tampilkan tur lagi, juga di Umum, memutar ulang tur sambutan.","docs.access.p1":"Saat aplikasi pertama kali dibuka, setelah lisensi, tur empat langkah menunjukkan editor dan tanda jedanya, kendali tempo, dan proyektor. Lewati, Esc, atau klik di luarnya menutup tur untuk seterusnya; Pengaturan → Umum → Tampilkan tur lagi memunculkannya kembali.","docs.access.p2":"Setiap kontrol menampilkan cincin fokus saat Anda menjangkaunya dari papan ketik. Tab tetap berada di dalam dialog yang terbuka, Esc menutupnya, dan fokus kembali ke tombol yang membukanya. Bilah telusur adalah penggeser sungguhan: tombol panah bergerak satu karakter, Page Up dan Page Down satu layar penuh, dan Home serta End menuju salah satu ujungnya.","docs.access.p3":"Jika sistem Anda meminta pengurangan gerakan, animasi dan efek buram dihilangkan sementara naskahnya sendiri tetap bergulir; dengan pengurangan transparansi, dialog meredupkan latar belakang alih-alih memburamkannya.","docs.problems.p1":"Saat terjadi kesalahan yang bisa diberitahukan aplikasi kepada Anda, pesannya punya tombol Laporkan di sampingnya. Setelah aplikasi mogok, saat dibuka berikutnya muncul bilah berisi Laporkan dan Abaikan.","docs.problems.p2":"Laporkan membuka halaman laporan Freally Teleprompt di peramban Anda, dengan rincian teknis yang sudah terisi: Anda bisa membacanya, tetapi tidak bisa mengubahnya. Tambahkan apa yang sedang Anda lakukan dan, jika mau, alamat email. Tidak ada yang dikirim kecuali Anda menekan Kirim di halaman itu, dan tidak ada yang pernah dikirim di latar belakang.","docs.problems.p3":"Sekali setiap kali dijalankan, aplikasi bertanya ke GitHub apakah ada versi yang lebih baru. Jika ada, Anda melihat nomor versinya dan catatan rilisnya lalu memilih ya atau tidak; pembaruan diperiksa terhadap kunci penandatanganan di dalam aplikasi sebelum dipasang. Saat Anda luring atau sudah memakai versi terbaru, aplikasi tidak mengatakan apa-apa. Periksa pembaruan di bilah alat bertanya lagi kapan saja.","docs.privacy.p1":"Tanpa akun dan tanpa telemetri. Naskah Anda adalah berkas .ftscript di komputer Anda, di tempat Anda menyimpannya, dan pembuat aplikasi tidak pernah menerimanya.","docs.privacy.p2":"Satu-satunya permintaan aplikasi ke internet adalah pemeriksaan pembaruan, yang tidak mengirim naskah, pengaturan, maupun pengenal apa pun. Laporan masalah hanya keluar dari halaman laporan di peramban Anda, saat Anda menekan Kirim. Proyektor dan cermin jaringan tetap berada di layar Anda sendiri dan jaringan Anda sendiri.","docs.privacy.p3":"Pembelajaran mesin dipakai di satu tempat: model ucapan untuk dikte, yang berjalan di komputer Anda dan mati sampai Anda menyalakannya. Pelengkapan otomatis adalah pencarian kamus, pembacaan lantang memakai suara bawaan sistem Anda, dan tidak ada yang Anda ketik atau ucapkan dikirim ke layanan AI.","kit.skip":"Lompat ke konten","kit.nav.site":"Situs","kit.nav.home":"Beranda","kit.nav.features":"Fitur","kit.nav.documentation":"Dokumentasi","kit.nav.changelog":"Log perubahan","kit.nav.language":"Bahasa","kit.nav.allApps":"Semua aplikasi Freally","kit.cta.features":"Lihat semua fitur","kit.cta.docs":"Baca dokumentasi","kit.price":"Freally Teleprompt gratis saat ini, tetapi mungkin tidak gratis selamanya: versi mendatang mungkin dijual.","kit.noDownloads":"Belum ada unduhan, dan kode sumbernya bersifat pribadi.","kit.label.overview":"Ikhtisar","kit.label.inside":"Di dalamnya","kit.label.roadmap":"Peta jalan","kit.ladder.done":"Selesai","kit.ladder.planned":"Direncanakan","kit.ladder.goal":"Tujuannya","kit.label.honesty":"Kejujuran","kit.family.label":"Keluarga Freally","kit.family.title":"<span class=\"hl-muted\">Satu keluarga.</span> <span class=\"hl-bright\">Delapan aplikasi.</span>","kit.cta.label":"Apa yang berubah","kit.cta.title":"<span class=\"hl-muted\">Setiap versi,</span> <span class=\"hl-bright\">tercatat.</span>","kit.cta.lede":"Log perubahan mencatat semua yang berubah di Freally Teleprompt, versi demi versi, dalam kedelapan belas bahasa.","kit.cta.changelog":"Baca log perubahan","kit.footer.thisApp":"Aplikasi ini","kit.footer.family":"Keluarga Freally","kit.footer.home":"Freally Products","kit.status.devVersion":"Dalam pengembangan · v1.5.0","kit.head.features":"<span class=\"hl-muted\">Semua yang dilakukannya,</span> <span class=\"hl-bright\">berdampingan.</span>","kit.label.numbers":"Dalam angka","kit.label.free":"Gratis hari ini","kit.label.compare":"Perbandingan","kit.label.principles":"Prinsip","kit.label.limits":"Batasan","kit.states.title":"Arti setiap status","kit.states.done":"sudah dibangun dan diberi tag, tetapi bukan unduhan di situs ini","kit.states.planned":"masih akan dibangun","kit.states.goal":"versi yang menjadi tujuan jalan ini","kit.states.ladder":"Lihat setiap anak tangga di jalan ini","kit.head.documentation":"<span class=\"hl-muted\">Cara kerjanya,</span> <span class=\"hl-bright\">langkah demi langkah.</span>","kit.search.placeholder":"Cari dalam dokumentasi","kit.docs.contents":"Daftar isi","kit.head.changelog":"<span class=\"hl-muted\">Setiap perubahan,</span> <span class=\"hl-bright\">versi demi versi.</span>","kit.changelog.lede":"Terbaru lebih dulu: semua yang berubah di Freally Teleprompt, dalam setiap bahasa situs ini.","kit.changelog.versions":"Versi","kit.changelog.unreleased":"Belum dirilis","kit.search.none":"Tidak ada yang cocok di situs ini.","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">Belum dirilis</span></span>","changelog.c205924de0fe":"Dokumentasi","changelog.3ba1bf71dedb":"<strong>Situs web dibangun ulang</strong> dengan desain keluarga Freally, dan situs ini berbicara dalam ke-18 bahasa aplikasi — termasuk log perubahan ini. Situs ini tidak menawarkan unduhan.","changelog.184abbf86c34":"<span class=\"release__meta\"><span class=\"release__ver\">v1.5.0</span></span><span class=\"release__title\">5 Agustus 2026</span>","changelog.4a6a7a1ffbc7":"Apa pun di ruangan bisa mengendalikan prompter.","changelog.6b02e0d363a4":"Ditambahkan","changelog.21717d79a98c":"<strong>Pedal kaki dan remote presentasi.</strong> Pedal adalah cara prompter benar-benar dikendalikan saat syuting — tangan Anda memegang kamera, bukan papan ketik. Buka <strong>Pintasan</strong>, tekan penetapan yang ingin Anda ubah, lalu injak pedalnya: apa pun yang dikirimnya, itulah yang disimpan, tanpa driver dan tanpa penyiapan. Sebagian besar pedal dan remote mengirim <code>F13</code>–<code>F24</code> justru karena tidak ada hal lain yang memakainya, dan kini tombol-tombol itu bisa ditetapkan seperti tombol lain mana pun.","changelog.87aef9902031":"<strong>Tombol yang bekerja saat Freally Teleprompt tidak berada di depan.</strong> Operator biasanya berada di aplikasi kamera, DAW, atau OBS, jadi setiap perintah pemutaran bisa diberi penetapan kedua yang dikirimkan sistem operasi di mana pun Anda berada.","changelog.d6a3a80ffa2c":"<strong>Tidak ada yang diklaim sampai Anda memintanya.</strong> Tidak ada tombol tingkat sistem yang didaftarkan secara bawaan — merebut satu tombol dari semua program lain tanpa diminta bukanlah hal yang pantas dilakukan aplikasi saat pertama kali dijalankan.","changelog.e134c7c903f4":"<strong>Tombol yang ditolak mengatakannya.</strong> Jika program lain sudah memiliki kombinasi itu, barisnya memberi tahu Anda, beserta alasannya. Di Wayland, yang sama sekali tidak mengizinkan aplikasi memesan tombol untuk seluruh sistem, dialognya juga mengatakan hal itu alih-alih menampilkan penetapan yang diam-diam tidak melakukan apa-apa.","changelog.dfedb41c2cf4":"<strong>Peta setiap perintah yang bisa dicari dan ditetapkan ulang</strong>, dengan deteksi bentrokan — cari berdasarkan nama perintahnya, atau berdasarkan tombolnya sendiri saat Anda ingin tahu apa yang sedang dilakukan <code>F13</code>. Hapus sebuah penetapan, atau kembalikan bawaan aslinya, kapan saja.","changelog.b74f3602a847":"<strong>Satu tabel menggerakkan semuanya.</strong> Pratinjau, jendela proyektor, pedal, dan tombol global tingkat sistem semuanya membaca penetapan yang sama, sehingga mengubah satu tombol mengubahnya di mana-mana sekaligus — termasuk proyektor pembaca, yang mengikuti penetapan ulang tanpa perlu dibuka kembali.","changelog.3573af4808a8":"Bilah spasi, tombol panah, dan Home tetap mengetik seperti biasa saat Anda menulis naskah: tombol tunggal hanya menjalankan perintahnya ketika Anda tidak sedang berada di editor.","changelog.1246fc93bca0":"Diperbaiki","changelog.07ff9553768e":"<strong>Mengimpor dokumen (<code>Import</code> dari 1.4.0), dengan satu tema: konverter yang diam-diam mengubah naskah Anda lebih buruk daripada konverter yang menolaknya.</strong>","changelog.0ec8d88f6052":"<strong>PDF tidak lagi mengaku tahu apa yang ditinggalkannya.</strong> Setiap format lain dibaca dengan menelusuri model dokumen, sehingga “tidak ada lagi yang tertinggal” adalah sesuatu yang benar-benar bisa diperiksa oleh pengimpor. PDF tidak punya struktur seperti itu — daftar kosong di sana berarti <em>kami tidak bisa tahu</em> — dan mengatakan sebaliknya adalah penenang palsu pada format yang paling mungkin membawa figur dan catatan kaki.","changelog.7ea47b0b9557":"<strong>Kotak teks Word tidak lagi dilaporkan sebagai gambar yang hilang.</strong> Teksnya selama ini sudah diimpor, dan pada saat yang sama dihitung sebagai gambar yang dibuang. Kini kotak teks menjadi paragrafnya sendiri alih-alih disisipkan ke baris mana pun yang kebetulan menjadi jangkarnya — “kita beralih DI DEPAN KAMERA ke gambar lebar” bukanlah yang tertulis di dokumen.","changelog.9962e4f893ac":"<strong>Gambar dan kepala halaman berulang dihitung sekali, dan hanya di tempat dipakai.</strong> Satu foto dilaporkan sebagai dua, dan Word menulis tiga kepala halaman dan tiga kaki halaman ke setiap dokumen, terpakai atau tidak — sehingga satu kepala halaman berulang dilaporkan sebagai enam. Operator yang membaca “Gambar yang ditinggalkan: 2” akan mencari gambar kedua yang tidak pernah ada.","changelog.07aaaf2b256f":"<strong>Karakter yang disimpan Word sebagai elemen tidak lagi hilang diam-diam</strong> — <code>co‑operate</code> terimpor sebagai <code>cooperate</code>. Glif dari font simbol kini dihitung sebagai sesuatu yang ditinggalkan alih-alih ditebak, karena titik kodenya adalah indeks ke dalam sebuah font, bukan sebuah karakter.","changelog.c15eb04425e7":"<strong>Berkas yang mengaku Unicode padahal bukan kini dilaporkan.</strong> Sebagian alat membubuhkan tiga byte penanda UTF-8 lalu tetap menulis teks Eropa Barat; berkas seperti itu terimpor dengan setiap karakter beraksen diganti <code>�</code> <strong>dan</strong> laporan yang menyatakan tidak ada yang dibuang — kegagalan persis yang hendak dicegah oleh catatan pengodean, tercapai lewat satu-satunya jalur yang melewatkan pemeriksaan itu.","changelog.3e2d09e4e749":"<strong>Menormalkan tanda pisah tetap tidak bisa menciptakan jeda.</strong> Spasi lebar-nol atau byte penanda nyasar di antara dua tanda pisah — yang rutin terbawa oleh teks dari web dan PDF — memecah rangkaiannya menjadi dua, dan <code>a —​— b</code> terimpor sebagai sesura <code> -- </code> yang tidak pernah ditulis siapa pun. RTF mengambil belokan keliru yang sama lewat rute yang berbeda.","changelog.cdc8dc821ad8":"<strong>RTF: gambar atau objek tertanam tidak lagi bocor ke dalam naskah.</strong> Muatan binernya dibaca seolah-olah teks, sehingga byte <code>}</code> pertama di dalamnya — yang muncul dalam data biner sembarang kira-kira sekali setiap 256 byte — mengakhiri lompatan terlalu cepat dan menuangkan sisanya ke dalam naskah.","changelog.c62855d7561c":"<strong>RTF: emoji dan karakter astral lainnya kini selamat.</strong> Karakter itu datang sebagai dua paruh pasangan surogat, dan tak satu pun paruhnya merupakan karakter tersendiri, sehingga keduanya dibuang. Spasi tak terputus dan tanda hubung tak terputus kini juga terimpor apa adanya.","changelog.456985ca40d6":"<strong>Aplikasi tidak lagi membeku saat dokumen dibaca.</strong> PDF yang besar bisa menahan jendela hingga sembilan puluh detik.","changelog.5ff5476a8e49":"<strong>Impor yang lambat tidak bisa lagi mendarat di dialog yang salah.</strong> Tutup dialognya, buka lagi, pilih berkas lain, dan hasil dokumen pertama dulu bisa tiba lalu menukar laporan, pratinjau, <em>dan</em> namanya — sehingga menekan Impor menyimpan naskah yang tidak Anda pilih, dengan nama yang berubah tanpa Anda sadari.","changelog.ca076d4847ef":"<strong>Penyimpanan yang gagal tidak lagi meninggalkan sisa.</strong> Jika penulisan gagal — folder baca-saja, disk penuh, berkas yang dikunci oleh klien sinkronisasi — naskah kosong tertinggal di pustaka dengan nama yang Anda pilih, dan mengimpor lagi gagal dengan pesan “naskah dengan nama itu sudah ada”. Anda harus menghapusnya dengan tangan. Pengembalian keadaan itu tidak pernah menyembunyikan galat yang sebenarnya.","changelog.81f5afe81f74":"<strong>Cari &amp; ganti (<code>Find</code> dari 1.4.0)</strong>","changelog.df4d2a98d916":"<strong>Ganti kini menyunting naskah sebagaimana adanya, bukan sebagaimana sesaat yang lalu.</strong> Baik Ganti maupun Ganti semua dihitung terhadap salinan yang tertinggal satu putaran di belakang editor — sehingga ucapan dikte yang tiba dalam selang waktu itu tertimpa dan hilang, dan posisi kecocokan bisa menunjuk ke karakter yang salah.","changelog.0cc222aab642":"<strong>Mengganti dengan teks yang mengandung kata yang Anda cari kini bergerak maju.</strong> Mengganti “apa” dengan “apakah” mengubah satu kata menjadi “apakahkah” setelah tiga kali tekan sementara dua kata lainnya tak tersentuh, dan penghitungnya menunjukkan “1 dari 3” sepanjang waktu.","changelog.fa5b9ccac936":"<strong>Laporan latihan (mode latihan dari 1.3.0)</strong>","changelog.e72cfed29d53":"<strong>Satu judul nyasar tidak lagi meruntuhkan laporan.</strong> Naskah dua belas paragraf yang membawa satu <code># Title</code> dari impor Markdown — atau satu baris daftar pengambilan gambar berbunyi <code>#3 CAMERA B</code> — menyusut dari dua belas baris menjadi dua, kehilangan waktu per paragraf yang menjadi alasan laporan itu ada. Satu penanda memberi label pada naskah; penanda itu tidak membaginya menjadi beberapa bagian.","changelog.cc295a583a87":"<span class=\"release__meta\"><span class=\"release__ver\">v1.4.0</span></span><span class=\"release__title\">4 Agustus 2026</span>","changelog.4f39388d525b":"Memasukkan naskah, dan menemukan jalan di dalamnya.","changelog.2bfa1e157a29":"<strong>Buka berkas yang dikirimkan kepada Anda.</strong> Sampai sekarang, satu-satunya cara teks sampai ke prompter adalah diketik atau ditempel, padahal tidak ada naskah yang datang dengan cara itu. <strong>Impor</strong> di bilah alat membaca <strong>Word (<code>.docx</code>), RTF, PDF, teks polos, dan Markdown</strong> lalu mengubahnya menjadi teks prompter yang bersih: paragraf dipertahankan; tebal, font, dan warna diratakan; tanda kutip melengkung, tanda pisah panjang, dan elipsis dinormalkan; dan berkas yang disimpan dengan pengodean yang salah dibaca serta dilaporkan alih-alih ditampilkan sebagai karakter kacau.","changelog.514edf636361":"<strong>Impor memberi tahu apa yang tidak bisa dibawanya</strong> — gambar, catatan kaki, komentar, kepala dan kaki halaman, alamat tautan, objek tertanam, masing-masing dengan jumlahnya. Konverter yang membuangnya diam-diam baru ketahuan saat syuting.","changelog.b9c0ccd7f34c":"<strong>Tidak ada yang disimpan sampai Anda mengatakannya.</strong> Anda melihat teks dan laporannya, menamai naskahnya, dan baru setelah itu sebuah berkas muncul di pustaka Anda — dan impor tidak akan pernah menimpa naskah yang sudah ada.","changelog.d2b1a7638b2a":"Menormalkan tanda pisah tidak akan pernah menciptakan jeda: <code>—</code> hasil atur huruf menjadi tanda hubung biasa, dan dua tanda itu berturut-turut tidak berubah menjadi token sesura <code> -- </code> milik aplikasi ini. Berkas <code>.txt</code> yang Anda tulis dengan sesura sungguhan tetap mempertahankannya.","changelog.90b7cc8211d3":"<strong>Penanda bagian, dengan daftar lompatan.</strong> Setiap baris yang diawali <code>#</code> — <code># Verse 2</code>, <code># Q&amp;A</code> — menjadi patokan, begitu pula setiap baris yang merupakan salah satu kata lewati Anda (<code>[Chorus]</code>, <code>Bridge</code>). Penanda muncul di daftar lompatan di samping bilah telusur, digaris pada bilah itu sendiri, dan <strong>berikutnya / sebelumnya</strong> menelusurinya. Tidak ada yang perlu dikonfigurasi, dan naskah Markdown yang diimpor tiba dengan daftarnya sudah tersusun.","changelog.697fb23f904c":"Sebelumnya membawa Anda ke awal bagian tempat Anda berada, lalu melewatinya — seperti tombol lagu sebelumnya.","changelog.ce1cd4f6f1f3":"<strong>Cari dan ganti</strong> (<code>Ctrl+F</code>), terbatas pada naskah yang terbuka: jumlah kecocokan yang diperbarui langsung, cocokkan huruf besar/kecil, hanya kata utuh, ganti dan ganti semua. Kecocokan saat ini disorot di editor tanpa mengeluarkan ketikan Anda dari kotak pencarian, dan ganti semua dibatalkan dengan <strong>satu</strong> kali Ctrl+Z.","changelog.164dc61c0ad5":"<strong>Statistik naskah</strong>, di bawah perkiraan waktu baca: jumlah kata, jumlah karakter, dan peringatan ketika sebuah baris cukup panjang untuk menjadi paragraf yang terbungkus. Hitungannya adalah apa yang benar-benar <strong>dibawakan</strong> — label yang dilewati dan token jeda tidak dihitung, sehingga cocok dengan durasi di sampingnya.","changelog.2a6141e43be0":"Diubah","changelog.24b7a7366360":"Bagian dalam laporan latihan kini dipisah berdasarkan penanda maupun label lewati, sehingga naskah yang ditulis dengan judul <code>#</code> dilatih bagian demi bagian tanpa kata kunci yang perlu dikonfigurasi. Sebuah bagian dinamai tanpa hiasannya: <code>[Verse 1]</code> dilaporkan sebagai <em>Verse 1</em>.","changelog.8f6fb4eb7f42":"Keamanan","changelog.9dc7532525e8":"Setiap pengurai dokumen berjalan di <strong>proses terpisah</strong>. Tiga dari lima format dibaca oleh pustaka pihak ketiga atas berkas yang tidak ditulis oleh aplikasi, dan versi rilis langsung berhenti saat terjadi galat fatal — sehingga PDF yang rusak bisa saja menjatuhkan prompter di tengah pembacaan. Proses terpisah juga memberi batas waktu pada pekerjaan itu dan menjauhkan memori pengurai yang lepas kendali dari aplikasi.","changelog.bbb6d70966f6":"Berkas sementara untuk impor dibuat di direktori yang baru dibuat dengan nama yang tak bisa ditebak, dan di Unix hanya pemiliknya yang bisa memasukinya.","changelog.0fdcda0b6a1e":"<span class=\"release__meta\"><span class=\"release__ver\">v1.3.0</span></span><span class=\"release__title\">3 Agustus 2026</span>","changelog.4245679cbf6a":"Membaca tepat waktu — dan kata-kata yang tidak seharusnya dihitung.","changelog.3a8bc8eb9047":"<strong>Ketuk tempo, dan aplikasi mempelajari tempo Anda.</strong> BPM selalu diubah menjadi kecepatan baca dengan satu angka: berapa karakter yang Anda lewati dalam satu ketukan. Dulu angka itu tebakan — tebakan yang sama untuk penyanyi balada dan rapper, padahal keduanya berselisih satu orde besaran. <strong>Pengaturan → Pewaktuan</strong> kini memungkinkan Anda mengetuk mengikuti tempo yang benar-benar Anda bawakan, dan mengukur angka itu terhadap kecepatan baca Anda sendiri alih-alih mengasumsikannya.","changelog.b94cb35d22f5":"Kalibrasi yang membuat sebagian rentang musik berada di luar jangkauan mesin <strong>mempersempit rentang yang ditawarkan kotak BPM</strong> alih-alih menampilkan angka yang diam-diam akan diubahnya tanpa sepengetahuan Anda.","changelog.4b0c4241773f":"<strong>Metronom.</strong> Klik opsional pada setiap ketukan saat naskah bergulir, ditekankan pada ketukan pertama birama, dengan hitung mundur awal yang sekaligus menjadi hitungan masuknya. Aplikasi menyintesisnya sendiri — tidak ada berkas audio di penginstal dan tidak ada yang diambil dari internet. Klik dijadwalkan terhadap jam audio dari indeks setiap ketukan, sehingga tidak bergeser terhadap guliran: diukur sepanjang pembacaan sepuluh menit pada tempo tercepat yang ditawarkan aplikasi, klik terakhir tetap tepat.","changelog.a0c53f6c5b09":"<strong>Penghitung birama dan ketukan</strong>, di samping permukaan baca, dengan <strong>garis birama pada bilah telusur</strong> — sehingga “enam belas birama” menjadi sesuatu yang bisa Anda lihat, bukan sesuatu yang Anda hitung di kepala. Keduanya hanya muncul saat Anda bekerja dengan tempo.","changelog.84aa1a93cd53":"<strong>Mode latihan, dengan laporan waktu.</strong> Baca naskah sampai habis dan aplikasi memberi tahu Anda, bagian demi bagian, berapa lama seharusnya dibandingkan berapa lama sebenarnya, dan menawarkan tempo yang benar-benar Anda bawakan. Mode ini mencatat <strong>waktu dan tidak ada yang lain</strong> — tidak ada mikrofon di dalamnya dan sama sekali tidak ada jalur audio, yang dibuktikan oleh sebuah tes alih-alih hanya dijanjikan di sini.","changelog.3bcd3e611ff3":"<strong>Peringatan tempo yang tenang</strong> saat berlatih, begitu pembacaan meleset lebih dari beberapa detik dari rencananya — sehingga bagian yang kelebihan waktu terlihat sebelum akhir, bukan sesudahnya.","changelog.440434188c4b":"<strong>Kata yang Anda baca tetapi tidak Anda bawakan.</strong> Masukkan “Chorus”, “Verse”, atau “Bridge” di <strong>Pengaturan → Pewaktuan</strong> dan baris yang hanya berisi salah satunya — <code>Chorus</code>, <code>[Verse 1]</code>, <code>## Bridge</code> — <strong>sama sekali tidak memakan waktu</strong>, sehingga lirik Anda tetap jatuh di birama tempat Anda menulisnya. Kata yang sama di dalam baris sungguhan hanya melewati dirinya sendiri, sehingga “kembali ke chorus sekarang” tetap memakan waktunya. Kata-kata itu tetap tampil di layar, diredupkan, dan pembacaan lantang tidak pernah mengucapkannya.","changelog.c06854290d9c":"<span class=\"release__meta\"><span class=\"release__ver\">v1.2.0</span></span><span class=\"release__title\">2 Agustus 2026</span>","changelog.b16edf96208e":"Tombol rekam, dan apa yang terjadi pada kata-kata setelah Anda mengucapkannya.","changelog.e03e88337492":"<strong>Tombol rekam adalah tombol, bukan kalimat.</strong> Kini tombol itu berupa lingkaran dengan glif di dalamnya — <strong>●</strong> untuk merekam, <strong>■</strong> untuk berhenti — dengan petunjuknya di samping, bukan di dalamnya, sehingga lebar kontrol tidak lagi berubah saat Anda memakainya. Warnanya mengikuti penunjuk Anda selain keadaannya: arahkan penunjuk ke tombol rekam dan warnanya menjadi hijau, dan saat sedang merekam, mengarahkan penunjuk ke tombol itu membuatnya merah. Menjauhkan penunjuk mengembalikannya tanpa mengubah apa yang akan dilakukannya.","changelog.f7a0e2da64e7":"<strong>Kata-kata hasil dikte kini melewati editor</strong>, yang memang sejak awal seharusnya menjadi jalurnya. Tiga hal mengikuti dari situ, dan masing-masing sebelumnya adalah kesalahan nyata:","changelog.8e6453161785":"<strong>Urungkan menarik kembali satu hal yang Anda ucapkan</strong>, bukan seluruh sesi. Dulu Ctrl+Z melompati semua yang telah Anda diktekan dalam satu langkah.","changelog.c4b4bb124914":"<strong>Teks yang Anda ketik saat merekam tetap tersimpan.</strong> Dulu hal berikutnya yang Anda ucapkan menimpanya.","changelog.f9033b43c6e5":"<strong>Kata-kata mendarat di posisi kursor Anda</strong>, tidak selalu di akhir naskah.","changelog.d766eb074a43":"Dikte melaporkan dirinya siap ketika <strong>folder</strong> model ucapan ada, meskipun model di dalamnya hilang atau baru tersalin setengah — sehingga muncul tombol rekam di layar yang hanya bisa gagal saat ditekan. Kini dikte memeriksa satu-satunya berkas yang tanpanya pengenal ucapan tidak bisa mulai.","changelog.4b11a58f4f52":"Pada instalasi di <strong>volume tanpa huruf drive</strong> (drive yang dipasang sebagai folder), jalur model yang diserahkan ke pengenal ucapan diubah menjadi jalur yang sama sekali tidak menunjuk apa pun. Kini jalurnya menunjuk ke model. Apakah pengenal ucapan kemudian berhasil memuatnya belum diuji pada susunan seperti itu — tetapi kegagalan di sana menyebutkan model mana yang tidak bisa dibukanya, alih-alih diam-diam mencari di tempat lain sama sekali.","changelog.c0965fe505ea":"Teks yang disisipkan dengan kursor di <strong>paling atas</strong> naskah bisa malah mendarat di bagian bawah. Editor tidak bisa membaca posisi kursor yang berada pada naskah secara keseluruhan alih-alih di dalam salah satu barisnya, dan menjawab dengan panjang seluruh teks — sehingga tempelan, atau baris hasil dikte, pergi ke akhir.","changelog.15f80b1047f4":"Dikte bisa melaporkan dirinya <strong>tidak tersedia padahal model yang sepenuhnya layak sudah terpasang</strong>: <code>vosk-model-en</code> yang nyasar atau baru tersalin setengah di folder data Anda lebih diutamakan daripada model di dalam aplikasi, lalu ditolak karena tidak lengkap. Kini aplikasi melewati folder yang tidak bisa dipakai dan memakai model bawaannya.","changelog.4ecc1ea9414e":"<code>npm run dev:vosk</code> untuk kontributor — mode pengembangan yang benar-benar bisa mendikte. Selain itu dikte hanya tersedia di versi rilis, yang membuatnya sulit dikerjakan.","changelog.9ef45f3d9beb":"Pencarian di situs dokumentasi kini menemukan <strong>dikte</strong> — fitur itu dirilis di 1.1.0 tetapi tidak ada di indeks, sehingga mencarinya tidak menghasilkan apa-apa. Ke arah sebaliknya, hasil pencarian yang hanya bisa berujung 404 sudah hilang: indeks bersama mencantumkan lima aplikasi Freally yang belum punya situs, yaitu 39 dari 109 entrinya.","changelog.1569fac6a9e5":"<code>THIRD-PARTY.md</code> mencatat <strong>Vosk</strong> (mesin, model, dan pustaka runtime MinGW untuk Windows) di samping font; <code>NOTICE</code> kini memuat petunjuk ke kode sumber yang bersesuaian untuk pustaka runtime tersebut. Kedua berkas disertakan di dalam penginstal.","changelog.a02b0fb176eb":"Catatan di Pengaturan untuk dikte menjelaskan apa yang terjadi ketika <strong>cermin LAN</strong> menyala: teks hasil dikte sampai ke para penontonnya begitu ditulis, sama seperti mengetik.","changelog.226b619dcadb":"<span class=\"release__meta\"><span class=\"release__ver\">v1.1.0</span></span><span class=\"release__title\">2 Agustus 2026</span>","changelog.d3ca2e44459c":"Satu cara memakai suara Anda, dan langsung berfungsi begitu Anda menyalakannya.","changelog.b370d746f358":"<strong>Tulis naskah Anda dengan berbicara</strong> (FT-33) — nyalakan <strong>Dikte</strong> di Pengaturan → Suara dan tombol rekam muncul di atas naskah. Tekan tombol itu dan apa yang Anda ucapkan akan dituliskan; tekan lagi untuk berhenti.","changelog.e02d4e39e7e3":"Tidak perlu pelatihan dan tidak perlu penyiapan: model ucapan disertakan di dalam penginstal, jadi fitur ini langsung berfungsi begitu Anda menyalakannya. Tidak ada yang diunduh saat berjalan dan tidak ada yang dikirim ke mana pun — pengenal ucapan dan modelnya ada di komputer Anda, dan itu tetap berlaku saat luring. Mikrofon hanya terbuka saat merekam, dan tidak ada yang Anda ucapkan ditulis ke berkas selain teksnya sendiri.","changelog.4118fb4fed0e":"Dihapus","changelog.9201332ddf55":"<strong>Perintah suara sudah dihapus.</strong> Fitur itu mengharuskan Anda merekam setiap perintah — putar, jeda, lebih cepat, lebih lambat, jeda berikutnya, kembali ke awal — dengan suara Anda sendiri sebelum satu pun berfungsi, lalu menahan sebuah tombol sambil berbicara. Sebelum rekaman itu Anda buat, menahan tombol membuka mikrofon tanpa menghasilkan apa pun, tanpa cara untuk membedakannya dari kerusakan. Dikte mencakup hal yang sama tanpa ada yang perlu dilatih.","changelog.8afda10a9120":"<strong>“Ikuti bacaan saya” sudah dihapus</strong> dengan alasan yang sama: satu cara yang jelas untuk memakai suara Anda lebih baik daripada tiga cara yang tumpang-tindih. Pekerjaan penyelarasan di baliknya masih ada sebagai pustaka dan mungkin kembali dalam bentuk lain.","changelog.119dd324728e":"Karena itu penginstalnya lebih besar daripada milik 1.0.0 — model ucapan berukuran sekitar 40 MB, dan kini selalu disertakan, dipakai atau tidak.","changelog.9133884e4863":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span></span><span class=\"release__title\">2 Agustus 2026</span>","changelog.3d6b5cab67c7":"Rilis pertama yang diterbitkan: semua dari Fase 3 (kendali suara tanpa tangan) dan sesi pemolesan Fase 5, dikemas sebagai penginstal bertanda tangan untuk Windows, macOS, dan Linux.","changelog.880aaef19013":"<strong>Tur sambutan satu menit</strong> (FT-50) — saat pertama kali Anda membuka aplikasi, empat langkah singkat memperkenalkan editor dan tanda jedanya, kendali tempo, dan proyektor. Lewati kapan saja, dan jalankan lagi kapan pun Anda mau dari <strong>Pengaturan → Umum → Tampilkan tur lagi</strong>.","changelog.0df57f3fd77c":"<strong>Tema yang mengikuti sistem Anda</strong> (FT-50) — selain Gelap dan Terang kini ada <strong>Sama seperti sistem saya</strong>, yang berganti bersama OS Anda dan langsung menggambar ulang saat komputer Anda berganti mode ketika matahari terbenam. Gelap tetap menjadi bawaan.","changelog.3d5dfaad60e5":"<strong>Perintah suara</strong> (FT-30, FT-31) — latih <strong>putar, jeda, lebih cepat, lebih lambat, jeda berikutnya, kembali ke awal</strong> dengan suara Anda sendiri (beberapa kali rekam untuk masing-masing) dan kendalikan prompter tanpa tangan. Indikator <strong>● Mendengarkan</strong> yang terlihat muncul setiap kali mikrofon terbuka; pilih <strong>tekan-untuk-bicara</strong> (mikrofon terbuka hanya selama Anda menahan tombol) atau <strong>selalu mendengarkan</strong>. <strong>Mati secara bawaan.</strong> Tanpa model: dicocokkan dengan pemrosesan sinyal klasik terhadap rekaman Anda sendiri, di perangkat.","changelog.689534aed982":"<strong>Mengikuti suara</strong> (FT-32, FT-34, FT-35) — mode <strong>opsional</strong> yang menggulir naskah agar terus mengikuti saat Anda membacanya dengan lantang, mengenali kata-kata naskah itu sendiri dengan model Vosk berlisensi Apache-2.0 yang disertakan. Mode ini <strong>beralih ke manual</strong> begitu kehilangan posisi Anda (sehingga tidak pernah menggulir ke tempat yang salah) dan hanya menggerakkan pratinjau operator, tidak pernah proyektor. <strong>Mati secara bawaan</strong>, dan tampil abu-abu beserta alasannya jika model tidak terpasang. Lapisan penyelarasan deterministik yang menentukan di bagian mana naskah Anda berada sepenuhnya dikembangkan sendiri dan diuji unit.","changelog.10a2d92eba51":"<strong>Penginstal, bertanda tangan dan bisa memperbarui diri</strong> (FT-51, FT-52) — Windows (<code>.exe</code> dan <code>.msi</code>), <code>.dmg</code> universal untuk macOS, serta AppImage dan <code>.deb</code> untuk Linux, semuanya dibangun dari satu commit bertag. Pembaru di dalam aplikasi memeriksa halaman rilis, dan setiap pembaruan diverifikasi terhadap kunci penandatanganan yang dibawa aplikasi — pembaruan yang tidak bisa diverifikasi ditolak alih-alih dipasang.","changelog.6831bb79a881":"<strong>Pemeriksaan aksesibilitas papan ketik dan pembaca layar</strong> (FT-50) — setiap kontrol yang bisa difokus kini menampilkan cincin fokus yang jelas; <strong>Tab</strong> tetap berada di dalam dialog yang terbuka alih-alih berkeliaran ke jendela di belakangnya; menutup dialog mengembalikan fokus ke tombol yang membukanya; dan daftar kategori Pengaturan kini melaporkan panel yang benar-benar sedang Anda lihat, bahkan saat pencarian sedang menyaringnya. Aplikasi juga menghormati <strong>kurangi gerakan</strong> di seluruh bagiannya. Guliran naskah itu sendiri sengaja tidak tersentuh oleh pengaturan itu — guliran itulah tujuan aplikasi ini, dan Anda sudah mengendalikan kecepatannya secara langsung.","changelog.54a57c3147c4":"Privasi","changelog.deae17e358ff":"<strong>Tanpa jaringan, selamanya.</strong> Perintah suara tidak pernah menyentuh jaringan atau disk — audio dicocokkan di memori terhadap rekaman Anda sendiri, dan tidak ada yang Anda ucapkan ditulis ke berkas. Mengikuti suara menjalankan pengenal ucapan sepenuhnya di perangkat; modelnya disertakan di penginstal dan tidak mengunduh apa pun saat berjalan.","changelog.0d7048033eef":"_<strong>Mengikuti suara belum bisa dipakai di versi ini.</strong> Pengenal ucapan membutuhkan model ucapan, dan rilis ini belum menyertakannya — fitur ini mendeteksi hal itu dan melaporkan dirinya tidak tersedia beserta alasannya, alih-alih gagal saat Anda menyalakannya. <strong>Perintah</strong> suara tidak terpengaruh: perintah tidak butuh model dan berfungsi di sini. Lapisan penyelarasan dan tata bahasa di bawahnya sudah lengkap dan teruji._","changelog.f8a8681a3de9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.300.0</span></span><span class=\"release__title\">22 Juli 2026</span>","changelog.49b18dafa9ac":"Pelengkapan otomatis luring di editor naskah: menyarankan sisa kata saat Anda mengetik, dalam salah satu dari 18 bahasa, dari daftar kata yang disertakan di dalam aplikasi.","changelog.863ad5535d5a":"<strong>Pelengkapan otomatis teks bayangan</strong> (FT-20, FT-21) — mulai sebuah kata dan sisanya muncul redup di depan kursor. <strong>Tab</strong> menerimanya, <strong>Esc</strong> menutupnya, dan terus mengetik melewatinya berarti mengabaikannya. Fitur ini juga melengkapi frasa umum secara utuh, begitu Anda menyelesaikan sebuah kata dan menekan spasi.","changelog.342d77799f0d":"<strong>Pengaturan pelengkapan otomatis</strong> — panel <strong>Editor</strong> baru dengan sakelar nyala/mati dan <strong>bahasa saran</strong>-nya sendiri, terpisah dari bahasa aplikasi, karena menulis naskah dalam satu bahasa sambil menjalankan aplikasi dalam bahasa lain adalah hal biasa.","changelog.bf3195662b89":"<strong>Tabel kata dan frasa untuk ke-18 bahasa</strong> (FT-22) — total sekitar 464.000 kata dan 345.000 frasa, disertakan di penginstal. Hanya bahasa yang benar-benar Anda pakai yang dimuat, sehingga aplikasi hanya memakai sekitar 0,5 MB memori pada satu waktu, bukan seluruh 12 MB.","changelog.9fb2fa59ae13":"<strong>Pemilih bahasa kini dimulai dengan English (bahasa Inggris), lalu berurutan menurut abjad nama setiap bahasa dalam bahasanya sendiri</strong> — Deutsch, Español, Français, dan seterusnya — dan tetap dalam urutan itu apa pun bahasa aplikasinya. Sebelumnya urutannya mengikuti nama dalam bahasa Inggris, sehingga urutannya bergeser tergantung pada apa yang Anda pilih.","changelog.6e805db44ddd":"<strong>Pelengkapan otomatis tidak pernah menyentuh jaringan.</strong> Fitur ini adalah pencarian dalam tabel di dalam penginstal — tanpa model, tanpa layanan, tanpa telemetri. Tidak ada yang Anda ketik dikirim ke mana pun, dan fitur ini bekerja saat komputer luring.","changelog.97775eaa1065":"<span class=\"release__meta\"><span class=\"release__ver\">v0.200.0</span></span><span class=\"release__title\">21 Juli 2026</span>","changelog.fdaeb02ed57c":"Teleprompter mandiri: naskah yang bisa Anda simpan, proyektor untuk pembaca, kontrol pemutaran sungguhan, dan prompter yang membacakan dirinya sendiri dengan lantang.","changelog.3c1c1f577fc6":"<strong>Pustaka naskah</strong> (FT-10) — berkas <code>.ftscript</code> yang bisa Anda buat, buka, ganti nama, dan hapus, dengan daftar terbaru dan <strong>simpan otomatis</strong> saat Anda mengetik. Berkas itu berupa teks UTF-8 polos dalam satu folder, sehingga sebuah naskah tetap bisa dibaca, dibandingkan perbedaannya, dan diselamatkan di editor teks mana pun jika aplikasi ini suatu saat tidak ada lagi. Aplikasi membuka kembali apa pun yang terakhir Anda buka.","changelog.54ba591e950e":"<strong>Cip sesura di editor</strong> (FT-11) — setiap <code> -- </code> / <code> --2 </code> di dalam baris ditampilkan sebagai pil atomik yang menunjukkan panjang jedanya. Tanda sisip hanya bisa berada sebelum atau sesudahnya, Backspace/Delete menghapus seluruh token sekali tekan, Shift+Panah memilihnya sebagai satu kesatuan, salin/potong membawa teks <code> -- </code> yang sebenarnya, dan naskah yang ditempel dirapikan spasinya yang berantakan. Mengetik tanda hubung kedua langsung mengubahnya menjadi jeda untuk Anda.","changelog.b9587c13e3c6":"<strong>Jendela proyektor</strong> (FT-12) — buka permukaan baca di layar mana pun yang tersambung, memenuhinya dari tepi ke tepi, dengan <strong>pembalikan cermin</strong> untuk kaca prompter pemisah sinar. Jendela ini berjalan dari keadaan guliran yang sama dengan pratinjau operator, sehingga keduanya tidak akan pernah berbeda pendapat soal posisi pembacaan, dan punya kontrol pemutaran, bilah telusur, serta pintasan papan ketiknya sendiri untuk orang yang benar-benar membaca.","changelog.d50b42582cf9":"<strong>Cermin LAN</strong> (FT-12) — cerminkan naskah yang bergulir ke ponsel, tablet, atau laptop kedua di jaringan Anda sendiri, lewat tautan dan kode QR yang ditampilkan aplikasi. Setiap perangkat mengatur ukuran fontnya sendiri tanpa mengubah apa yang dilihat orang lain. <strong>Mati secara bawaan</strong>, hanya terbuka untuk komputer ini sendiri sampai Anda secara tegas membukanya ke jaringan, dilindungi kunci yang dibuat baru setiap kali aplikasi dijalankan, dan <strong>baca-saja</strong> — tidak ada yang dikirim peramban yang bisa mengubah guliran, naskah, atau pengaturan.","changelog.00b57b5822cd":"<strong>Kontrol pemutaran sungguhan</strong> (FT-13) — putar / jeda / berhenti / mundur / maju cepat sebagai tombol SVG yang layak dengan <strong>tahan-untuk-mengulang</strong>, bilah telusur bergaya YouTube dengan waktu baca yang telah berjalan dan totalnya (jeda sesura ikut dihitung) serta pratinjau kata di titik mana pun saat penunjuk diarahkan ke sana, klik-sebuah-kata-untuk-mulai, menggeser posisi dengan roda tetikus, dan pintasan papan ketik di proyektor.","changelog.d3d56659d660":"<strong>Mode kecepatan BPM</strong> (FT-14) — baca tempo sebagai karakter per detik atau sebagai <strong>BPM (20–250)</strong> untuk pembawaan musikal. Mesinnya tetap memakai karakter/detik di seluruh bagian; BPM adalah mode tampilan dan masukan, dan setiap BPM yang bisa Anda ketik jatuh di dalam rentang mesin itu sendiri alih-alih diam-diam dipangkas tanpa sepengetahuan Anda.","changelog.5fe2620dd908":"<strong>Kendali tampilan</strong> (FT-15) — jenis huruf, ketebalan, warna teks, margin samping, jarak baris, dan <strong>posisi garis baca</strong> di layar. Pengaturan ini tinggal di mesin, bukan di keadaan satu jendela, sehingga pratinjau, proyektor, dan cermin LAN selalu terlihat sama.","changelog.ca6865582cd0":"<strong>Bacakan dengan sintesis ucapan bawaan OS</strong> (FT-16) — minta prompter membacakan naskah kepada Anda pada tempo yang telah Anda atur, untuk menguji pewaktuan sebelum pengambilan. Sorotan mengikuti kata yang diucapkan, sesura menjadi keheningan sungguhan (<code>--</code> tidak pernah diucapkan sebagai “tanda hubung”), dan menelusuri membuat ucapan ikut melompat. Fitur ini <strong>hanya untuk pratinjau</strong>: tidak pernah menggerakkan proyektor pembaca. Memakai suara yang sudah dimiliki OS Anda (Windows OneCore/SAPI, macOS AVSpeechSynthesis, Linux Speech Dispatcher / espeak-ng) — tidak ada mesin ucapan yang disertakan.","changelog.cdfbacda0108":"<strong>Setiap bahasa kini tampil, di setiap komputer.</strong> Aplikasi menyertakan font Noto untuk ke-18 bahasa yang didukungnya — Latin, Yunani, Sirilik, Vietnam, Arab, Dewanagari, Jepang, Korea, dan Tionghoa Sederhana. Beralih ke bahasa Jepang di komputer tanpa font Jepang terpasang dulu menampilkan kotak-kotak alih-alih antarmuka; kini aplikasi membawa apa yang dibutuhkannya. Hanya subset karakter yang benar-benar dipakai bahasa terpilih yang dimuat, dan font ini juga menjadi cadangan bagi setiap jenis huruf baca, sehingga memilih “Berkait” tidak akan pernah membuat suatu bahasa tak terbaca. Font-font ini berada di bawah SIL Open Font License; pemberitahuannya disertakan bersama aplikasi sebagai <code>THIRD-PARTY.md</code>.","changelog.d1589cdefe34":"<strong>Aplikasi menggambar jendelanya sendiri.</strong> Tanpa bilah judul OS: judul di tengah, dengan Pengaturan, Tentang, dan perkecil / perbesar-pulihkan / tutup di kanan — susunan yang sama dengan Freally Player, sehingga jendela-jendela dalam rangkaian ini terlihat serupa. Bilahnya bisa diseret, klik ganda tetap memaksimalkan, dan ukuran jendela tetap bisa diubah dari setiap tepi dan sudut.","changelog.83b865a057ab":"<strong>Pengaturan kini menjadi dialog pengaturan yang sesungguhnya</strong>, dengan bentuk yang sama seperti milik Freally Capture: bilah samping kategori (Umum, Membaca, Tampilan, Proyektor, Jaringan) dengan kotak pencarian, dan kaki dialog <strong>OK / Batal / Terapkan</strong>. Terapkan nonaktif sampai ada yang benar-benar berubah, dan sebuah titik menandai kategori yang sudah Anda sunting tetapi belum diterapkan.","changelog.dd1a689ff484":"<strong>Perkecil ke baki sistem</strong> (Pengaturan → Umum). Mati secara bawaan. Jika dinyalakan, memperkecil akan menyembunyikan jendela dan menaruh ikon di baki; memulihkan akan memunculkan jendela kembali <strong>dan menghilangkan ikonnya</strong> — aplikasi berada di bilah tugas atau di baki, tidak pernah di keduanya. Menu baki diterjemahkan seperti bagian aplikasi lainnya.","changelog.4124706702a9":"<strong>Ikon aplikasi kini berupa karya seni lengkap di setiap ukuran.</strong> <code>0.100.0</code> mengganti ikon berukuran 48px ke bawah dengan “F” yang dipotong, hanya glif, dengan alasan tulisan merek di dalam karya seni tidak terbaca pada ukuran sekecil itu. Ternyata satu tanda yang konsisten lebih penting daripada tanda yang terbaca tetapi berbeda, jadi potongan itu dihapus — bilah tugas, baki, dan favicon kini menampilkan ikon yang sama.","changelog.c347bd2b4305":"Ditemukan oleh tinjauan atas fase ini, sebelum rilis:","changelog.47424533ef57":"<strong>Cip jeda bisa muncul di tempat prompter tidak berhenti.</strong> Editor dan pembacaan lantang masing-masing membawa salinan sendiri tata bahasa <code> -- </code>, tanpa batas yang diterapkan mesin guliran — sehingga <code>--2.5.3</code> digambar sebagai jeda yang langsung dilewati prompter. Ketiganya kini berbagi satu pemindai.","changelog.b434155bb7d9":"<strong>Mengeklik kanan ikon baki memulihkan jendela</strong> alih-alih membuka menu, sehingga “Keluar” milik baki itu sendiri tidak bisa dijangkau.","changelog.ec0cf2fce1a1":"<strong>Tombol-tombol perjanjian saat pertama dijalankan bisa berada di bawah tepi bawah jendela</strong> sejak aplikasi menggambar bilah judulnya sendiri.","changelog.9d5731455d75":"<strong>Pengaturan bisa menampilkan nilai yang tidak dipakai aplikasi.</strong> Angka yang dibatasi oleh inti aplikasi (misalnya port di bawah 1024) tetap ditampilkan sebagai angka yang diketik sampai aplikasi dijalankan ulang; kini dialog menampilkan apa yang benar-benar disimpan.","changelog.db89654f4e78":"<strong>Mencari di Pengaturan bisa meninggalkan panel yang salah di layar</strong>, tanpa kategori yang disorot untuk menjelaskannya.","changelog.39ed54f3671f":"<strong>Berhenti kini menjadi satu tindakan di dalam mesin</strong> alih-alih pasangan jeda-dan-mundur yang disusun oleh tiap tombol, sehingga apa pun lainnya yang menghentikan guliran berperilaku sama.","changelog.e806a291cfc3":"Pengujian","changelog.b6521470f6ed":"<strong>Playwright kini mencakup setiap fitur Fase 1 yang bisa dijangkaunya</strong> — seluruh siklus hidup pustaka naskah, perilaku cip, pemilih layar, kontrol pemutaran, konversi BPM, alur tampilan, dan kontrak bahwa pembacaan lantang tidak pernah menyentuh guliran bersama. Jembatan tiruan merekam panggilan IPC, sehingga tes memastikan apa yang sebenarnya diminta antarmuka dari inti aplikasi.","changelog.965a9f5ce8e2":"<strong>Aplikasi kini dijalankan dan difoto di Windows, macOS, dan Linux pada setiap putaran CI</strong> (<code>scripts/app-screenshot.mjs</code>), dan gagal jika aplikasi mati saat mulai atau tidak menggambar apa pun. Kompilasi yang berhasil dan webview yang tampil adalah dua hal yang berbeda.","changelog.33678f48d52f":"<strong>Setiap bahasa diperiksa keterbacaannya, bukan hanya teksnya.</strong> Sebuah tes mengalihkan aplikasi ke masing-masing dari 18 lokal dan membuktikan bahwa setiap karakter antarmukanya tercakup oleh font yang disertakan. Aksara yang hilang tampil sebagai kotak-kotak, yang terlihat seperti teks yang berfungsi bagi tangkapan layar dan bagi setiap pemeriksaan lain — sehingga bahasa Arab, Hindi, Jepang, Korea, dan Tionghoa masing-masing bisa rusak diam-diam, dan hanya bagi orang yang membacanya.","changelog.503e7e57035d":"<strong>Terjemahan yang diam-diam kembali ke bahasa Inggris kini menggagalkan build.</strong> Proses terjemahan massal meninggalkan bahasa Inggris untuk apa pun yang tidak bisa diterjemahkannya, dan hasilnya tetap bisa diurai dan dirilis seolah sudah selesai. Pengecualian yang sah — “OK”, “Port”, nama diri — dicantumkan beserta alasannya.","changelog.8b79c1c1b492":"<strong>Tampilan di Linux kini terbukti, bukan diasumsikan.</strong> Tangkapan layar CI berjalan di dalam kontainer dengan perender perangkat lunak, karena mesin Linux polos milik GitHub tidak punya GL yang berfungsi dan menghasilkan jendela kosong entah aplikasinya sehat atau tidak — pemeriksaan yang tidak mungkin gagal tidak memberi tahu kami apa pun.","changelog.bf256044a419":"Semua yang benar-benar tidak bisa diotomatiskan — monitor kedua, kaca prompter, ucapan yang terdengar, ponsel di Wi-Fi Anda — kini punya <strong>latihan langkah demi langkah</strong> di <code>Live-To-Do-List.md</code>.","changelog.8a7525b1492f":"Catatan","changelog.f38acbd9b28b":"<strong>Tetap tanpa AI, tanpa akun, tanpa telemetri.</strong> Cermin LAN menyajikan naskah Anda ke perangkat yang Anda arahkan kepadanya, di jaringan Anda sendiri; tidak ada yang diunggah atau diteruskan. Satu-satunya permintaan keluar yang dibuat aplikasi tetaplah pemeriksaan pembaruan.","changelog.aadc02e8de62":"<span class=\"release__meta\"><span class=\"release__ver\">v0.100.0</span></span><span class=\"release__title\">21 Juli 2026</span>","changelog.7bfe7961d71b":"Fase kerangka: aplikasi kini bisa dibangun, berjalan, dan terkunci sampai perjanjian disetujui, dengan mesin gulir berbasis karakter yang dipindahkan dari Freally Capture.","changelog.19bd3024e088":"<strong>Kerangka Tauri v2</strong> (FT-00) — ruang kerja Rust (<code>src-tauri</code>) ditambah antarmuka React/TypeScript (<code>ui</code>), dengan susunan perkakas yang sama seperti Freally Capture: <code>ci.yml</code>, <code>scripts/ci-local.mjs</code>, <code>deny.toml</code>, dan <code>rust-toolchain.toml</code> yang dipatok versinya, sehingga <code>npm run ci:local</code> menjalankan seluruh gerbang sejak hari pertama.","changelog.045988032f64":"<strong>Set ikon</strong> (FT-01) — dihasilkan dari karya seni sumber oleh <code>scripts/make-icons.py</code>, untuk Windows, macOS, dan Linux ditambah favicon situs web. Ukuran 48px ke bawah memakai varian <strong>“F” hanya glif</strong>, karena tulisan merek yang tertanam di karya seni tidak terbaca di bawah 64px (diukur, bukan ditebak).","changelog.e0471332722d":"<strong>Mesin teleprompter berbasis karakter</strong> (FT-02) — <code>teleprompter.rs</code> dan kembaran TypeScript-nya <code>ui/src/lib/caesura.ts</code>, dipindahkan dari Freally Capture: posisi guliran berdasarkan karakter yang terlihat, jeda sesura <code> -- </code> di dalam baris (<code> --2 </code> untuk jeda dengan durasi khusus), kendali telusur/langkah/kecepatan, dan hitung mundur sebelum mulai. Pratinjau dan proyektor menata teks di satu panggung berlebar tetap lalu menskalakannya dengan CSS, sehingga keduanya membungkus baris di kolom yang persis sama.","changelog.a1b0c9f8ea89":"<strong>Cangkang aplikasi satu jendela</strong> (FT-03) — bilah alat, masukan naskah, dan permukaan prompter langsung, dengan <strong>Pengaturan</strong> pada pola draf/terapkan (tidak ada yang berlaku sampai Terapkan; Batal memulihkan persis apa yang Anda miliki) dan fondasi i18n Fluent untuk <strong>18 lokal</strong>.","changelog.b45c55ac02ea":"<strong>Situs dokumentasi + log perubahan</strong> (FT-04) — situs disajikan oleh GitHub Pages dari <code>/docs</code>, sama seperti aplikasi Freally lainnya.","changelog.8b96bdf6151d":"<strong>Gerbang EULA saat pertama dijalankan</strong> (FT-05) — aplikasi tidak bisa dipakai sampai perjanjian disetujui. Persetujuan diberi versi dan <strong>dipertahankan di setiap penyimpanan pengaturan</strong> (galat yang sempat lolos ke rilis Freally Capture; kini ada tes regresi untuknya).","changelog.d5361112a7c1":"<strong>Pelapor masalah dan pemeriksaan pembaruan</strong> — pelapor crash standar Havoc (laporan lokal yang sudah dibersihkan, pemberitahuan asli sistem “berhenti tiba-tiba”, mulai ulang, dan pengiriman lewat GitHub/Gmail/email yang Anda picu sendiri) serta pemeriksaan pembaruan saat aplikasi dibuka yang menampilkan versi dan catatan rilis yang sebenarnya sebelum melakukan apa pun.","changelog.198e4f9204b8":"<strong>Tanpa AI, tanpa akun, tanpa telemetri.</strong> Satu-satunya permintaan keluar adalah pemeriksaan pembaruan; permintaan itu tidak mengirim apa pun tentang Anda, komputer Anda, atau naskah Anda.","changelog.04d59a3b7905":"Tautan unduhan di situs hanyalah penampung sampai alur rilis tersedia.","changelog.a3c71b90162b":"Keterbatasan yang diketahui","changelog.4d18eba61c3f":"<strong>Belum ada penginstal.</strong> <code>0.100.0</code> adalah tonggak kode sumber; alur rilis bertanda tangan untuk tiap OS adalah fase selanjutnya.","changelog.57871c6e9623":"<strong>Pembaruan otomatis belum aktif.</strong> Pembaru dirilis tanpa kunci publik penandatanganannya, sehingga ia menolak setiap paket alih-alih memasang paket yang belum terverifikasi — ia gagal dengan aman, tetapi juga tidak bisa berhasil. “Periksa pembaruan” akan melaporkan galat sampai penandatanganan kode tersedia."};
